-- Multi-branch memberships (tasks §3 memberships scoping, §4b sale snapshot).
-- Generated by drizzle-kit; the two backfill UPDATEs at the end are
-- hand-written and reviewed (30 October 2026).
--
--   * selling_branch_id: the branch that sold the membership and issued its
--     purchase invoice. Its money and cancellation stay there; the hours can
--     be used at any branch (route inventory gap 5). Nullable for now so the
--     current code keeps working until the new code is deployed; a later
--     enforcement migration re-runs the backfill and sets NOT NULL.
--   * tier_usual_hours_minutes / tier_usual_price_paise: the tier's usual
--     values at sale time, for the agreed-versus-usual comparison. Left empty
--     for memberships sold before the snapshot existed.
--
-- Backfill: the branch on the purchase invoice, else the primary branch.
-- Idempotent: it fills only rows that are still empty.
ALTER TABLE "spa_membership" ADD COLUMN "tier_usual_hours_minutes" integer;--> statement-breakpoint
ALTER TABLE "spa_membership" ADD COLUMN "tier_usual_price_paise" integer;--> statement-breakpoint
ALTER TABLE "spa_membership" ADD COLUMN "selling_branch_id" text;--> statement-breakpoint
ALTER TABLE "spa_membership" ADD CONSTRAINT "spa_membership_selling_branch_id_branch_id_fk" FOREIGN KEY ("selling_branch_id") REFERENCES "public"."branch"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "spa_membership_selling_branch_id_idx" ON "spa_membership" USING btree ("selling_branch_id");--> statement-breakpoint
UPDATE "spa_membership" AS m
   SET "selling_branch_id" = i."branch_id"
  FROM "invoice" AS i
 WHERE m."selling_branch_id" IS NULL
   AND i."id" = m."invoice_id";--> statement-breakpoint
UPDATE "spa_membership"
   SET "selling_branch_id" = (
         SELECT "id" FROM "branch" ORDER BY "is_primary" DESC, "display_order", "id" LIMIT 1
       )
 WHERE "selling_branch_id" IS NULL;
